*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF06004.xml";
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd"); // 오늘날짜
scwin.pLIST_PROMT_SEQ = "";
scwin.listPromtSeq = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/*
 * init()
 */
scwin.fn_init = function() {
    var YY = scwin.vCurDate.substr(0, 4);
    var YY_1 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 1;
    var YY_2 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 2;
    var YY_3 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 3;
    var YY_4 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 4;
    $c.stf.setObjectValue(edt_INTIW_DD_FROM, YY + "0101");
    $c.stf.setObjectValue(edt_INTIW_DD_TO, YY + "1231");
    var strCbd_SME_YN = "전체^all," + YY + "^" + YY + "," + YY_1 + "^" + YY_1 + "," + YY_2 + "^" + YY_2 + "," + YY_3 + "^" + YY_3 + "," + YY_4 + "^" + YY_4 + "," + "기타^Z";
    cmb_PeriodTp.CBData = strCbd_SME_YN;

    // 담당자
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listInvstgEmpKoList";
    dts_EmpNo.DataID = encodeURI(url);
    dts_EmpNo.Reset();
    var strCbd = "^전체";
    if (dts_EmpNo.getTotalRow() > 0) {
        for (var i = 1; i <= dts_EmpNo.getTotalRow(); i++) {
            strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_EmpNo.getCellData(i, "EMP_NO") + "^" + dts_EmpNo.getCellData(i, "DEP_EMP_NM");
        }
        cmb_EMP_NO.CBData = strCbd; //	담당자				

    }
    cmb_EMP_NO.setSelectedIndex(0);
    var arrCid = [{
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD"
    }, {
        cid: "VENT_ADM_INST_CD",
        cnm: "cmb_REL_INST_NM"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='INTVIEW_ACTIV_CD','VENT_ADM_INST_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (var i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        if (arrCid[i].cid == 'INTVIEW_ACTIV_CD' || arrCid[i].cid == 'VENT_ADM_INST_CD') {
            strCbd = "^' '";
        }
        for (var j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};




/*
 * 면담일 연도별검색Setting
 */
scwin.fn_setDate = function(pYear) {
    if (pYear == "all" || pYear == "Z") {
        $c.stf.setObjectValue(edt_INTIW_DD_FROM, "");
        $c.stf.setObjectValue(edt_INTIW_DD_TO, "");
    } else {
        $c.stf.setObjectValue(edt_INTIW_DD_FROM, pYear + "0101");
        $c.stf.setObjectValue(edt_INTIW_DD_TO, pYear + "1231");
    }
};



/*
 * 상장유치실적조회
 */
scwin.fn_list_sync = function() {
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPromtPrfmKoList";
    url += "&inputMessageId=LISTPROMTPRFMKOLIST_IN&outputMessageId=LISTPROMTPRFMKOLIST_INOUT";
    url += "&INTIW_DD_TYPE=" + $c.stf.getObjectValue(cmb_PeriodTp);
    url += "&INTIW_DD_FROM=" + $c.stf.getObjectValue(edt_INTIW_DD_FROM);
    url += "&INTIW_DD_TO=" + $c.stf.getObjectValue(edt_INTIW_DD_TO);
    url += "&COM_NM=" + $c.stf.getObjectValue(txb_COM_NM);
    url += "&EMPLOYEE_NO=" + $c.stf.getObjectValue(cmb_EMP_NO);
    url += "&EMPLOYEE_NM=" + cmb_EMP_NO.getText();
    url += "&CORP_REG_NO=" + txb_CORP_REG_NO.getValue();
    url += "&MAJAGNT_CONTRT_TRD_YN=" + $c.stf.getObjectValue(chk_MAJAGNT_CONTRT_TRD_YN);
    url += "&LIST_EDU_YN=" + $c.stf.getObjectValue(chk_LIST_EDU_YN);
    url += "&EXT_AUDT_YN=" + $c.stf.getObjectValue(chk_EXT_AUDTR_YN);
    url += "&REL_INST_NM=" + $c.stf.getObjectValue(cmb_REL_INST_NM);
    url += "&INTVIEW_METHD_CD=" + $c.stf.getObjectValue(cmb_INTVIEW_METHD_CD);
    url += "&CAP_TOTAMT_FROM=" + $c.stf.getObjectValue(edt_CAP_TOTAMT_FROM);
    url += "&CAP_TOTAMT_TO=" + $c.stf.getObjectValue(edt_CAP_TOTAMT_TO);
    url += "&SALES_FROM=" + $c.stf.getObjectValue(edt_SALES_FROM);
    url += "&SALES_TO=" + $c.stf.getObjectValue(edt_SALES_TO);
    url += "&BZ_PROFT_AMT_FROM=" + $c.stf.getObjectValue(edt_BZ_PROFT_AMT_FROM);
    url += "&BZ_PROFT_AMT_TO=" + $c.stf.getObjectValue(edt_BZ_PROFT_AMT_TO);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};



/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, "기업정보 조회", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};


/*
 * OnDblClick Event 처리
 */
scwin.fn_OpenDetail = async function(row) {
    var pageNM;
    scwin.fn_setListPromtSeq(row);
    pageNM = "ULDSTF06003";
    await $c.frame.CreateDialogFrame("LIST_PROMTHIS", "/lstmgt/" + pageNM + ".gfm", " 기업정보 입력", 3, 3, 1265, 860, "window");
};
scwin.fn_setListPromtSeq = function(obj) {
    scwin.pLIST_PROMT_SEQ = dts_List.getCellData(eval(obj), "LIST_PROMT_SEQ");
};
scwin.fn_getListPromtSeq = function() {
    return scwin.pLIST_PROMT_SEQ;
};
scwin.fn_delete = function() {
    var rtn = confirm("'" + dts_List.getCellData(dts_List.getRowPosition(), "COM_NM") + "'" + ' 항목을 삭제하시겠습니까?');
    if (rtn == 1) {
        var trsIdx = "";
        trsIdx = TR_JOB_DELETE;
        //dts_ContentsDel.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ContentsDel.insertRow();
        scwin.listPromtSeq = dts_List.getCellData(dts_List.getRowPosition(), "LIST_PROMT_SEQ");
        dts_ContentsDel.setCellData(1, "LIST_PROMT_SEQ", dts_List.getCellData(dts_List.getRowPosition(), "LIST_PROMT_SEQ"));
        trs_Delete.Action = "/ListPromtHistMgt.do?method=saveListPromtPrfmKoList" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyValue = "JSP(I:pInput=dts_ContentsDel)";
        trs_Delete.Parameters = "TRS_IDX=" + trsIdx + ",LIST_PROMT_SEQ=" + scwin.listPromtSeq;
        trs_Delete.Post();
    }
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_INTIW_DD_FROM, edt_INTIW_DD_TO)) {
        scwin.fn_list_sync();
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Excel_onclick = function() {
    scwin.fn_ExcelDown();
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.fn_setListPromtSeq(row);
    if ("ATTACH_FILE1" == colid && dts_List.getCellData(row, "ATTACH_FILE1") != "") {
        // 파일첨부 1
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ + "&SEQ=1&gubun=41";
    } else if ("ATTACH_FILE2" == colid && dts_List.getCellData(row, "ATTACH_FILE2") != "") {
        //파일첨부 2
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ + "&SEQ=2&gubun=41";
    } else if ("ATTACH_FILE3" == colid && dts_List.getCellData(row, "ATTACH_FILE3") != "") {
        //파일첨부 3
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ + "&SEQ=3&gubun=41";
    } else {
        scwin.fn_OpenDetail(row);
    }
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar2(edt_INTIW_DD_TO);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_INTIW_DD_FROM);
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_INTIW_DD_FROM);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    scwin.fn_setDate($c.stf.getObjectValue(cmb_PeriodTp));
};
scwin.txb_COM_NM_onkeydown = function() {
    if (window.event.keyCode == 13) {
        if ($c.stf.compareFromToDate2(edt_INTIW_DD_FROM, edt_INTIW_DD_TO)) {
            scwin.fn_list_sync();
        }
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var url = frame.srcUrl;
    var arr = url.split("?");
    var arr2 = url.split("&");
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.fn_init();
    if (arr2.length > 1) {
        $c.stf.setObjectValue(cmb_INTVIEW_METHD_CD, arr2[1]);

        //setObjectValue(edt_INTIW_DD_TO, arr2[3]) ;	
        $c.stf.setObjectValue(cmb_PeriodTp, arr2[4]);
        $c.stf.setObjectValue(edt_INTIW_DD_FROM, arr2[2]);
        $c.stf.setObjectValue(edt_INTIW_DD_TO, arr2[3]);
    }
    scwin.fn_list_sync();
};
scwin.dts_List_OnRowPosChanged = function(row) {
    /*if(row > 0 ) {
    	btn_delete.src = "../img/btn_delete.gif";			
    	btn_delete.disabled = false;	
    } else {
    	btn_delete.src = "../img/btn_delete_d.gif";			
    	btn_delete.disabled = true;	
    }*/
};
scwin.trs_Delete_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    //frame.CloseFrame();	
    scwin.fn_list_sync();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
    scwin.fn_list_sync();
};
scwin.chk_MAJAGNT_CONTRT_TRD_YN_onclick = function() {
    //  chb_Grp_All.checked =false;

};
scwin.chk_LIST_EDU_YN_onclick = function() {
    //  chb_Grp_All.checked =false;

};
scwin.btn_Input_onclick = function() {
    scwin.fn_OpenDetail(-1);
};
scwin.btn_Input_Excel_onclick = async function() {
    var inputType = $c.stf.getObjectValue(cmb_INPUT_EXCEL_TP_CD);
    if (inputType == "1") {
        await $c.frame.CreateDialogFrame("ULDSTF06010", "/lstmgt/ULDSTF06010.gfm", "주관계약체결 등록", 300, 200, 740, 400, "window");
    } else if (inputType == "2") {
        await $c.frame.CreateDialogFrame("ULDSTF06011", "/lstmgt/ULDSTF06011.gfm", "상장교육수료일 등록", 300, 200, 740, 400, "window");
    } else if (inputType == "3") {
        await $c.frame.CreateDialogFrame("ULDSTF06012", "/lstmgt/ULDSTF06012.gfm", "유관기관 등록", 300, 200, 740, 400, "window");
    } else if (inputType == "4") {
        await $c.frame.CreateDialogFrame("ULDSTF06013", "/lstmgt/ULDSTF06013.gfm", "재무정보 등록", 300, 200, 740, 400, "window");
    } else if (inputType == "5") {
        await $c.frame.CreateDialogFrame("ULDSTF06014", "/lstmgt/ULDSTF06014.gfm", "투자유치 등록", 300, 200, 740, 400, "window");
    }
};
